Brief:
A paper kite rides the wind over the rooftops. Tap to rise, avoid the chimneys and collect ribbons while the wind slowly speeds up.

Plan:
{"gameType":"arcade-run","input":"tap-anywhere","lang":"en","loop":"Tap to lift the paper kite, dodging chimneys and collecting ribbons as the wind speeds up. Hitting a chimney ends the run; your ribbon count is the score.","slug":"kite-on-the-wind","style":"paper-cut","title":"Kite on the Wind"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Kite on the Wind</title>
7| <style>
8|   html, body {
9|     margin: 0;
10|     padding: 0;
11|     width: 100%;
12|     height: 100%;
13|     background: #f4ecd8;
14|     overflow: hidden;
15|     font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
16|   }
17|   canvas {
18|     display: block;
19|     touch-action: none;
20|   }
21| </style>
22| </head>
23| <body>
24| <canvas id="game"></canvas>
25| <script>
26| const CARTRIDGE = {
27|   send(type, payload = {}) {
28|     window.parent.postMessage(
29|       { source: "cartridge", v: 1, type, payload },
30|       "*",
31|     );
32|   },
33| };
34| </script>
35| <script>
36| (function(){
37|   const canvas = document.getElementById('game');
38|   const ctx = canvas.getContext('2d');
39| 
40|   let DPR = Math.max(1, window.devicePixelRatio || 1);
41|   let W = 0, H = 0;
42| 
43|   function resize(){
44|     W = window.innerWidth;
45|     H = window.innerHeight;
46|     DPR = Math.max(1, window.devicePixelRatio || 1);
47|     canvas.width = Math.round(W * DPR);
48|     canvas.height = Math.round(H * DPR);
49|     canvas.style.width = W + 'px';
50|     canvas.style.height = H + 'px';
51|     ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
52|   }
53|   window.addEventListener('resize', resize);
54|   resize();
55| 
56|   // Palette
57|   const COLORS = {
58|     bg: '#f4ecd8',
59|     layer: '#e07a5f',
60|     accent: '#3d405b',
61|     highlight: '#81b29a'
62|   };
63| 
64|   // Seeded jitter helper for paper-cut edges
65|   function mulberry32(a){
66|     return function(){
67|       a |= 0; a = (a + 0x6D2B79F5) | 0;
68|       let t = Math.imul(a ^ (a >>> 15), 1 | a);
69|       t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
70|       return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
71|     };
72|   }
73|   const jitterRand = mulberry32(12345);
74|   function jitteredPoints(points, amt){
75|     return points.map(p => [
76|       p[0] + (jitterRand() - 0.5) * amt * 2,
77|       p[1] + (jitterRand() - 0.5) * amt * 2
78|     ]);
79|   }
80| 
81|   function drawPaperShape(pointsArr, fillColor, shadow){
82|     ctx.save();
83|     if (shadow !== false){
84|       ctx.shadowColor = 'rgba(61,64,91,0.35)';
85|       ctx.shadowBlur = 6;
86|       ctx.shadowOffsetX = 0;
87|       ctx.shadowOffsetY = 3;
88|     }
89|     ctx.fillStyle = fillColor;
90|     ctx.beginPath();
91|     ctx.moveTo(pointsArr[0][0], pointsArr[0][1]);
92|     for (let i=1;i<pointsArr.length;i++){
93|       ctx.lineTo(pointsArr[i][0], pointsArr[i][1]);
94|     }
95|     ctx.closePath();
96|     ctx.fill();
97|     ctx.restore();
98|   }
99| 
100|   function roundRectPath(x,y,w,h,r){
101|     ctx.beginPath();
102|     ctx.moveTo(x+r, y);
103|     ctx.arcTo(x+w, y, x+w, y+h, r);
104|     ctx.arcTo(x+w, y+h, x, y+h, r);
105|     ctx.arcTo(x, y+h, x, y, r);
106|     ctx.arcTo(x, y, x+w, y, r);
107|     ctx.closePath();
108|   }
109| 
110|   function drawRoundedPlate(x,y,w,h,r,color){
111|     ctx.save();
112|     ctx.shadowColor = 'rgba(61,64,91,0.35)';
113|     ctx.shadowBlur = 6;
114|     ctx.shadowOffsetX = 0;
115|     ctx.shadowOffsetY = 3;
116|     ctx.fillStyle = color;
117|     roundRectPath(x,y,w,h,r);
118|     ctx.fill();
119|     ctx.restore();
120|   }
121| 
122|   // Game state
123|   let last = 0;
124|   let running = false;
125|   let paused = false;
126|   let started = false; // whether boot happened
127|   let score = 0;
128|   let ribbons = 0;
129|   let time = 0;
130|   let elapsedSinceStart = 0;
131| 
132|   // Kite (player)
133|   let kiteX, kiteY, kiteVY;
134|   const kiteSize = 28;
135|   const gravity = 520;
136|   const liftVY = -230;
137| 
138|   // World
139|   let worldSpeed = 160;
140|   const speedRamp = 3.2; // px/s^2 growth
141|   let chimneys = [];
142|   let ribbonsList = [];
143|   let clouds = [];
144|   let spawnTimer = 0;
145|   let ribbonSpawnTimer = 0;
146| 
147|   const GROUND_Y_FRAC = 0.86;
148| 
149|   function resetWorld(){
150|     kiteX = () => W * 0.28;
151|     kiteY = H * 0.45;
152|     kiteVY = 0;
153|     score = 0;
154|     ribbons = 0;
155|     time = 0;
156|     elapsedSinceStart = 0;
157|     worldSpeed = 160;
158|     chimneys = [];
159|     ribbonsList = [];
160|     spawnTimer = 2.2; // fairness: first hazard well ahead
161|     ribbonSpawnTimer = 1.2;
162|   }
163| 
164|   function initClouds(){
165|     clouds = [];
166|     for (let i=0;i<6;i++){
167|       clouds.push({
168|         x: Math.random()*1200,
169|         y: 40 + Math.random()*140,
170|         s: 0.6 + Math.random()*0.8,
171|         speed: 12 + Math.random()*18
172|       });
173|     }
174|   }
175| 
176|   let kiteYVal = 0;
177|   function fullReset(){
178|     kiteYVal = H*0.45;
179|     kiteVY = 0;
180|     score = 0;
181|     ribbons = 0;
182|     time = 0;
183|     elapsedSinceStart = 0;
184|     worldSpeed = 160;
185|     chimneys = [];
186|     ribbonsList = [];
187|     spawnTimer = 2.2;
188|     ribbonSpawnTimer = 1.2;
189|     running = false;
190|     paused = false;
191|   }
192| 
193|   fullReset();
194|   initClouds();
195| 
196|   function backToTitle(){
197|     fullReset();
198|   }
199| 
200|   function spawnChimney(){
201|     const groundY = H * GROUND_Y_FRAC;
202|     const gapH = Math.max(140, 260 - elapsedSinceStart*2);
203|     const gapY = 60 + Math.random() * (groundY - gapH - 120);
204|     chimneys.push({
205|       x: W + 60,
206|       w: 54,
207|       gapY: gapY,
208|       gapH: gapH,
209|       passed: false
210|     });
211|   }
212| 
213|   function spawnRibbon(){
214|     const groundY = H * GROUND_Y_FRAC;
215|     ribbonsList.push({
216|       x: W + 40,
217|       y: 60 + Math.random() * (groundY - 160),
218|       r: 14,
219|       taken: false
220|     });
221|   }
222| 
223|   function act(){
224|     kiteVY = liftVY;
225|   }
226| 
227|   function advance(dt){
228|     elapsedSinceStart += dt;
229|     time += dt;
230|     worldSpeed += speedRamp * dt;
231| 
232|     // clouds always drift for idle liveliness
233|     for (const c of clouds){
234|       c.x -= c.speed * dt;
235|       if (c.x < -120) c.x = W + 120 + Math.random()*80;
236|     }
237| 
238|     // kite physics
239|     kiteVY += gravity * dt;
240|     kiteYVal += kiteVY * dt;
241|     const groundY = H * GROUND_Y_FRAC;
242|     if (kiteYVal < 10) { kiteYVal = 10; kiteVY = 0; }
243|     if (kiteYVal > groundY - kiteSize) {
244|       kiteYVal = groundY - kiteSize;
245|       crash();
246|       return;
247|     }
248| 
249|     // spawn hazards
250|     spawnTimer -= dt;
251|     if (spawnTimer <= 0){
252|       spawnChimney();
253|       spawnTimer = Math.max(1.1, 2.3 - elapsedSinceStart*0.03);
254|     }
255|     ribbonSpawnTimer -= dt;
256|     if (ribbonSpawnTimer <= 0){
257|       spawnRibbon();
258|       ribbonSpawnTimer = 1.4 + Math.random()*1.2;
259|     }
260| 
261|     // move chimneys
262|     for (const c of chimneys){
263|       c.x -= worldSpeed * dt;
264|       if (!c.passed && c.x + c.w < W*0.28){
265|         c.passed = true;
266|         score += 1;
267|         CARTRIDGE.send('score', { value: score + ribbons });
268|       }
269|     }
270|     chimneys = chimneys.filter(c => c.x + c.w > -20);
271| 
272|     // move ribbons
273|     for (const r of ribbonsList){
274|       r.x -= worldSpeed * dt;
275|     }
276|     ribbonsList = ribbonsList.filter(r => r.x > -40 && !r.taken);
277|   }
278| 
279|   function collide(){
280|     const px = W*0.28;
281|     const py = kiteYVal;
282|     const pr = kiteSize*0.5;
283| 
284|     // chimneys
285|     for (const c of chimneys){
286|       if (px + pr > c.x && px - pr < c.x + c.w){
287|         if (py - pr < c.gapY || py + pr > c.gapY + c.gapH){
288|           crash();
289|           return;
290|         }
291|       }
292|     }
293| 
294|     // ribbons
295|     for (const r of ribbonsList){
296|       if (r.taken) continue;
297|       const dx = px - r.x;
298|       const dy = py - r.y;
299|       const dist = Math.sqrt(dx*dx + dy*dy);
300|       if (dist < pr + r.r){
301|         r.taken = true;
302|         ribbons += 1;
303|         CARTRIDGE.send('score', { value: score + ribbons });
304|       }
305|     }
306|   }
307| 
308|   function crash(){
309|     if (!running) return;
310|     running = false;
311|     CARTRIDGE.send('end', { reason: 'lose', value: score + ribbons });
312|   }
313| 
314|   // Drawing
315|   function drawBackground(){
316|     ctx.fillStyle = COLORS.bg;
317|     ctx.fillRect(0,0,W,H);
318| 
319|     // clouds - simple paper-cut puffs
320|     for (const c of clouds){
321|       const pts = jitteredPoints([
322|         [c.x-30*c.s, c.y],
323|         [c.x-10*c.s, c.y-18*c.s],
324|         [c.x+15*c.s, c.y-20*c.s],
325|         [c.x+35*c.s, c.y-6*c.s],
326|         [c.x+30*c.s, c.y+14*c.s],
327|         [c.x-20*c.s, c.y+14*c.s]
328|       ], 1.5);
329|       drawPaperShape(pts, '#ffffff', false);
330|     }
331| 
332|     // ground
333|     const groundY = H * GROUND_Y_FRAC;
334|     ctx.save();
335|     ctx.shadowColor = 'rgba(61,64,91,0.3)';
336|     ctx.shadowBlur = 6;
337|     ctx.shadowOffsetY = -3;
338|     ctx.fillStyle = COLORS.highlight;
339|     ctx.fillRect(0, groundY + kiteSize, W, H - groundY - kiteSize);
340|     ctx.restore();
341|   }
342| 
343|   function drawChimney(c){
344|     const groundY = H * GROUND_Y_FRAC;
345|     // top part
346|     const topPts = jitteredPoints([
347|       [c.x, 0],
348|       [c.x + c.w, 0],
349|       [c.x + c.w, c.gapY],
350|       [c.x, c.gapY]
351|     ], 1.5);
352|     drawPaperShape(topPts, COLORS.layer);
353| 
354|     // bottom part
355|     const botPts = jitteredPoints([
356|       [c.x, c.gapY + c.gapH],
357|       [c.x + c.w, c.gapY + c.gapH],
358|       [c.x + c.w, groundY + kiteSize],
359|       [c.x, groundY + kiteSize]
360|     ], 1.5);
361|     drawPaperShape(botPts, COLORS.layer);
362| 
363|     // accent stripe caps
364|     ctx.save();
365|     ctx.fillStyle = COLORS.accent;
366|     ctx.fillRect(c.x-3, Math.max(0,c.gapY-10), c.w+6, 10);
367|     ctx.fillRect(c.x-3, c.gapY + c.gapH, c.w+6, 10);
368|     ctx.restore();
369|   }
370| 
371|   function drawRibbon(r){
372|     ctx.save();
373|     ctx.translate(r.x, r.y);
374|     ctx.rotate(Math.sin(time*3 + r.x*0.05) * 0.3);
375|     const pts = jitteredPoints([
376|       [-14,-4],[-4,-12],[6,-10],[14,0],[6,10],[-4,12],[-14,4]
377|     ], 1.2);
378|     drawPaperShape(pts, COLORS.accent);
379|     ctx.restore();
380|   }
381| 
382|   function drawKite(){
383|     const x = W*0.28;
384|     const y = kiteYVal;
385|     const s = kiteSize;
386|     ctx.save();
387|     ctx.translate(x,y);
388|     const tilt = Math.max(-0.4, Math.min(0.4, -kiteVY/600));
389|     ctx.rotate(tilt);
390| 
391|     // tail
392|     ctx.strokeStyle = COLORS.accent;
393|     ctx.lineWidth = 2;
394|     ctx.beginPath();
395|     ctx.moveTo(-s*0.2, s*0.6);
396|     for (let i=1;i<=4;i++){
397|       ctx.lineTo(-s*0.2 - i*6, s*0.6 + Math.sin(time*6+i)*5 + i*4);
398|     }
399|     ctx.stroke();
400| 
401|     // kite body (diamond)
402|     const pts = jitteredPoints([
403|       [0,-s],
404|       [s*0.8,0],
405|       [0,s],
406|       [-s*0.8,0]
407|     ], 1.5);
408|     drawPaperShape(pts, COLORS.highlight);
409| 
410|     // inner accent diamond
411|     const innerPts = jitteredPoints([
412|       [0,-s*0.45],
413|       [s*0.35,0],
414|       [0,s*0.45],
415|       [-s*0.35,0]
416|     ], 1);
417|     drawPaperShape(innerPts, COLORS.layer, false);
418| 
419|     ctx.restore();
420|   }
421| 
422|   function drawHUD(){
423|     const total = score + ribbons;
424|     const text = 'Ribbons: ' + total;
425|     ctx.font = 'bold 20px sans-serif';
426|     const tw = ctx.measureText(text).width;
427|     drawRoundedPlate(14, 14, tw + 28, 38, 10, '#ffffff');
428|     ctx.fillStyle = COLORS.accent;
429|     ctx.fillText(text, 28, 40);
430|   }
431| 
432|   function drawTitleScreen(){
433|     drawBackground();
434|     drawKite();
435| 
436|     const pulse = 0.5 + 0.5*Math.sin(time*3);
437|     ctx.save();
438|     ctx.globalAlpha = 0.7 + pulse*0.3;
439|     const text = 'Tap to begin';
440|     ctx.font = 'bold 28px sans-serif';
441|     const tw = ctx.measureText(text).width;
442|     drawRoundedPlate(W/2 - tw/2 - 20, H*0.3 - 30, tw+40, 56, 14, '#ffffff');
443|     ctx.fillStyle = COLORS.accent;
444|     ctx.textAlign = 'left';
445|     ctx.fillText(text, W/2 - tw/2, H*0.3 + 6);
446|     ctx.restore();
447| 
448|     ctx.font = 'bold 22px sans-serif';
449|     const t2 = 'Kite on the Wind';
450|     const tw2 = ctx.measureText(t2).width;
451|     drawRoundedPlate(W/2 - tw2/2 - 16, H*0.15 - 26, tw2+32, 46, 12, '#ffffff');
452|     ctx.fillStyle = COLORS.layer;
453|     ctx.fillText(t2, W/2 - tw2/2, H*0.15 + 4);
454|   }
455| 
456|   function drawGameOverOverlay(){
457|     ctx.save();
458|     ctx.fillStyle = 'rgba(244,236,216,0.6)';
459|     ctx.fillRect(0,0,W,H);
460|     ctx.font = 'bold 30px sans-serif';
461|     const t = 'Run Over';
462|     const tw = ctx.measureText(t).width;
463|     drawRoundedPlate(W/2 - tw/2 - 20, H*0.35 - 34, tw+40, 60, 14, '#ffffff');
464|     ctx.fillStyle = COLORS.accent;
465|     ctx.fillText(t, W/2 - tw/2, H*0.35 + 6);
466| 
467|     const s2 = 'Ribbons: ' + (score+ribbons);
468|     ctx.font = 'bold 22px sans-serif';
469|     const tw2 = ctx.measureText(s2).width;
470|     drawRoundedPlate(W/2 - tw2/2 - 16, H*0.35 + 40, tw2+32, 44, 12, '#ffffff');
471|     ctx.fillStyle = COLORS.layer;
472|     ctx.fillText(s2, W/2 - tw2/2, H*0.35 + 70);
473| 
474|     ctx.font = 'bold 18px sans-serif';
475|     const s3 = 'Tap to try again';
476|     const tw3 = ctx.measureText(s3).width;
477|     drawRoundedPlate(W/2 - tw3/2 - 14, H*0.35 + 100, tw3+28, 38, 10, '#ffffff');
478|     ctx.fillStyle = COLORS.accent;
479|     ctx.fillText(s3, W/2 - tw3/2, H*0.35 + 126);
480|     ctx.restore();
481|   }
482| 
483|   let awaitingRestart = false;
484| 
485|   function draw(){
486|     if (!running && !awaitingRestart){
487|       drawTitleScreen();
488|       return;
489|     }
490|     drawBackground();
491|     for (const c of chimneys) drawChimney(c);
492|     for (const r of ribbonsList) if (!r.taken) drawRibbon(r);
493|     drawKite();
494|     drawHUD();
495| 
496|     if (paused){
497|       ctx.save();
498|       ctx.fillStyle = 'rgba(61,64,91,0.4)';
499|       ctx.fillRect(0,0,W,H);
500|       ctx.font = 'bold 26px sans-serif';
501|       const t = 'Paused';
502|       const tw = ctx.measureText(t).width;
503|       drawRoundedPlate(W/2-tw/2-18, H/2-30, tw+36, 50, 12, '#ffffff');
504|       ctx.fillStyle = COLORS.accent;
505|       ctx.fillText(t, W/2-tw/2, H/2+2);
506|       ctx.restore();
507|     }
508| 
509|     if (awaitingRestart && !running){
510|       drawGameOverOverlay();
511|     }
512|   }
513| 
514|   function frame(now){
515|     const dt = Math.min((now - last) / 1000, 0.05);
516|     last = now;
517|     if (running && !paused){
518|       advance(dt);
519|       collide();
520|       if (!running){
521|         awaitingRestart = true;
522|       }
523|     } else if (!running){
524|       time += dt;
525|       for (const c of clouds){
526|         c.x -= c.speed * dt * 0.5;
527|         if (c.x < -120) c.x = W + 120 + Math.random()*80;
528|       }
529|     }
530|     draw();
531|     requestAnimationFrame(frame);
532|   }
533| 
534|   canvas.style.touchAction = 'none';
535|   canvas.addEventListener('pointerdown', (event) => {
536|     event.preventDefault();
537|     if (paused) return;
538|     if (!running && awaitingRestart){
539|       fullReset();
540|       awaitingRestart = false;
541|       running = true;
542|       CARTRIDGE.send('start');
543|       return;
544|     }
545|     if (!running){
546|       running = true;
547|       CARTRIDGE.send('start');
548|       return;
549|     }
550|     act();
551|   });
552| 
553|   window.addEventListener('message', (event) => {
554|     const data = event.data;
555|     if (!data || data.source !== 'cartridge-host') return;
556|     if (data.type === 'pause') paused = true;
557|     if (data.type === 'resume') paused = false;
558|     if (data.type === 'reset'){
559|       awaitingRestart = false;
560|       backToTitle();
561|     }
562|   });
563| 
564|   requestAnimationFrame((t) => {
565|     last = t;
566|     draw();
567|     CARTRIDGE.send('boot', { title: 'Kite on the Wind', gameType: 'arcade-run', lang: 'en' });
568|     requestAnimationFrame(frame);
569|   });
570| })();
571| </script>
572| </body>
573| </html>
